/* Instructional-design blueprints that place the comprehensive teaching inside the learning path. */
window.NC_LEARNING_BLUEPRINTS={
  'lesson-1':{
    duration:'70–90 minutes · saves as you go',level:'Nutrition counsellor in training',
    why:'Nutrition basics becomes useful when you can read the number, perform the calculation, explain the limitation and apply the result without overclaiming.',
    outcomes:['Classify nutrients by function and energy contribution.','Choose the correct reference value for the question being asked.','Calculate energy and percentages without mixing grams, Calories, Daily Values or serving sizes.','Explain how processing, solubility and bioavailability change interpretation.','Combine ABCD evidence and evaluate supplement claims without diagnosing or overpromising.'],
    integratedSteps:[
      {id:'l1-core-1',title:'Build the nutrient framework',sectionIds:['l1-2'],activityId:'l1-interactive-1',keyIdea:'Carbohydrate, protein and fat provide energy; vitamins, minerals and water are essential to function without providing Calories.'},
      {id:'l1-core-2',title:'Read sugars, starch and fibre structurally',sectionIds:['l1-4'],prompt:'Without looking, explain how sucrose, lactose and maltose differ.',keyIdea:'Sucrose is glucose + fructose, lactose is glucose + galactose, and maltose is glucose + glucose.'},
      {id:'l1-core-3',title:'Choose the number that answers the question',sectionIds:['l1-3'],activityId:'l1-interactive-2',keyIdea:'EAR, RDA, AI, UL, EER and DV have different jobs; none is a universal personal target.'},
      {id:'l1-core-4',title:'Turn grams into energy',sectionIds:['l1-5'],activityId:'l1-interactive-3',keyIdea:'Convert each macronutrient separately with 4–4–9, add the energy, then adjust for the amount actually eaten.'},
      {id:'l1-core-5',title:'Apply AMDRs to the whole pattern',sectionIds:['l1-6'],prompt:'What two details must be known before interpreting an AMDR?',keyIdea:'AMDRs depend on age and describe the whole diet’s energy distribution—not the composition of every individual food.'},
      {id:'l1-core-6',title:'Keep three label percentages separate',sectionIds:['l1-7'],activityId:'l1-interactive-4',keyIdea:'Grams, percent Daily Value and percent of energy use different units and denominators.'},
      {id:'l1-core-7',title:'Distinguish enrichment, fortification and whole grain',sectionIds:['l1-8'],activityId:'l1-interactive-5',keyIdea:'Restoring selected nutrients does not recreate every component removed during refining.'},
      {id:'l1-core-8',title:'Use vitamin categories without oversimplifying',sectionIds:['l1-9'],prompt:'Why is “water soluble means harmless” an unsafe shortcut?',keyIdea:'Solubility affects handling and storage, not automatic safety; vitamin B12 and excessive supplemental B6 show why simple rules need exceptions.'},
      {id:'l1-core-9',title:'Follow minerals from food to absorption',sectionIds:['l1-10'],activityId:'l1-interactive-6',keyIdea:'The amount listed in a food is not always the amount available for use; form, meal context and health status matter.'},
      {id:'l1-core-10',title:'Explain why water matters without Calories',sectionIds:['l1-11'],prompt:'Name three functions of water that do not involve supplying energy.',keyIdea:'Water supports reactions, transport, waste removal and temperature regulation while contributing no Calories.'},
      {id:'l1-core-11',title:'Separate a mechanism from a health outcome',sectionIds:['l1-12'],prompt:'What evidence is still needed after a compound shows antioxidant activity?',keyIdea:'A laboratory mechanism or antioxidant effect does not by itself establish disease prevention, safety or benefit in people.'},
      {id:'l1-core-12',title:'Distinguish nutrient density from energy density',sectionIds:['l1-13'],prompt:'How can a food be nutrient dense without being low in energy?',keyIdea:'Nutrient density describes nutrients relative to energy; energy density describes Calories relative to weight or amount.'},
      {id:'l1-core-13',title:'Combine ABCD evidence before interpreting',sectionIds:['l1-14','l1-15'],activityId:'l1-interactive-7',keyIdea:'Assessment combines anthropometric, biochemical, clinical and dietary evidence; intake and impaired use are different pathways that can coexist.'},
      {id:'l1-core-14',title:'Interrogate the supplement claim',sectionIds:['l1-16'],activityId:'l1-interactive-8',keyIdea:'A biological function does not prove that a product produces the promised outcome, and regulatory language differs by country.'}
    ],
    modules:[
      {id:'framework',label:'Module 1',title:'Build the nutrient framework',stepIds:['l1-core-1','l1-core-2'],summary:'Learn what nutrients do, which ones supply energy and how carbohydrate structures differ.'},
      {id:'numbers',label:'Module 2',title:'Read nutrition numbers correctly',stepIds:['l1-core-3','l1-core-4','l1-core-5','l1-core-6'],summary:'Choose the right reference, calculate with 4–4–9 and keep serving, DV and energy percentages separate.'},
      {id:'composition',label:'Module 3',title:'Understand composition and availability',stepIds:['l1-core-7','l1-core-8','l1-core-9','l1-core-10'],summary:'Connect processing, vitamin handling, mineral absorption and water functions to real interpretation.'},
      {id:'reasoning',label:'Module 4',title:'Reason without overclaiming',stepIds:['l1-core-11','l1-core-12','l1-core-13','l1-core-14'],summary:'Evaluate evidence, combine assessment domains and respond to supplement claims within scope.'}
    ],
    recap:['Know what job each nutrient and reference number performs.','Keep grams, Calories, servings, Daily Values and energy percentages distinct.','Treat processing, solubility and bioavailability as context—not slogans.','Combine ABCD evidence instead of diagnosing from one observation.','Ask whether the evidence supports the product outcome actually being claimed.']
  },
  'lesson-2':{
    duration:'75–95 minutes · saves as you go',level:'Nutrition counsellor in training',
    why:'Preconception support begins before pregnancy is recognized and connects reproductive biology, nutritional status, feasible access, precise nutrient numbers and safe care coordination.',
    outcomes:['Explain why preparation begins before a positive pregnancy test without promising an outcome.','Distinguish reproductive timing, nutritional status and unsupported diagnostic inference.','Separate routine supplement guidance, total-intake references and individualized treatment.','Build a feasible risk-reduction plan that includes access, products, medicines and exposures.','Use READY, teach-back and referral boundaries in realistic cases.'],
    integratedSteps:[
      {id:'l2-deep-1',title:'Start before the positive test',sectionIds:['l2-3'],activityId:'l2-interactive-1',keyIdea:'Preparation supports health because early development can precede pregnancy recognition; it does not guarantee conception or outcome.'},
      {id:'l2-deep-2',title:'Assess nutritional status beyond one food record',sectionIds:['l2-4'],activityId:'l2-interactive-4',keyIdea:'Availability, intake, absorption, use, losses, stores and function are different links in nutritional status.'},
      {id:'l2-deep-3',title:'Master folate form, figure and timing',sectionIds:['l2-5'],activityId:'l2-interactive-2',keyIdea:'Keep folate, folic acid, DFE, units, total-intake references and prevention guidance attached to their exact meaning.'},
      {id:'l2-deep-4',title:'Separate three kinds of nutrient number',sectionIds:[],activityId:'l2-interactive-3',keyIdea:'A total-intake reference is not automatically a supplement instruction or a treatment dose.'},
      {id:'l2-deep-5',title:'Build the complete nutrient map',sectionIds:['l2-6'],activityId:'l2-interactive-5',keyIdea:'For each nutrient, connect role, food source, reference value, product amount and the limitation of that number.'},
      {id:'l2-deep-6',title:'Build a feasible pattern—not a fertility diet',sectionIds:['l2-7'],activityId:'l2-interactive-8',keyIdea:'Start with the barrier the person actually faces and choose one repeatable action that preserves adequate energy and familiar foods.'},
      {id:'l2-deep-7',title:'Keep fish categories and time windows attached',sectionIds:[],activityId:'l2-interactive-6',keyIdea:'Do not collapse category-specific mercury guidance into “avoid all fish.”'},
      {id:'l2-deep-8',title:'Audit medicines, supplements and products safely',sectionIds:['l2-8'],activityId:'l2-interactive-7',keyIdea:'Review the full product list and coordinate qualified care; do not stop essential medicines or select treatment doses independently.'},
      {id:'l2-deep-9',title:'Address alcohol, caffeine, smoking and partner factors',sectionIds:['l2-9'],prompt:'Which claims require a clinical outcome rather than only a changed biomarker?',keyIdea:'Reduced exposure can support health, but a semen marker or hormone change does not prove pregnancy or live-birth benefit.'},
      {id:'l2-deep-10',title:'Use READY and teach-back',sectionIds:['l2-10'],prompt:'What makes the “Y” in READY different from simply giving advice?',keyIdea:'“Your next achievable step” is agreed, feasible and reviewable; teach-back checks the clarity of the explanation rather than obedience.'},
      {id:'l2-deep-11',title:'Resolve the supplied-test distinctions',sectionIds:['l2-11'],prompt:'Why should ambiguous or incorrect options be flagged instead of memorized?',keyIdea:'Test preparation must keep the science, the question’s wording and any source ambiguity visibly separate.'},
      {id:'l2-deep-12',title:'Work through Jane’s metabolic pattern',sectionIds:['l2-12'],prompt:'Which findings are observations, and which conclusion still requires clinical follow-up?',keyIdea:'Multiple metabolic-syndrome features can be recognized without turning a study exercise into a diagnosis; the low-HDL wording error must remain flagged.'}
    ],
    modules:[
      {id:'biology',label:'Module 1',title:'Prepare early and assess context',stepIds:['l2-deep-1','l2-deep-2'],summary:'Connect reproductive timing with the full pathway from food access to nutrient function.'},
      {id:'numbers',label:'Module 2',title:'Master folate and nutrient numbers',stepIds:['l2-deep-3','l2-deep-4','l2-deep-5'],summary:'Read the form, unit and purpose before using a folate, iron or prenatal-product number.'},
      {id:'plan',label:'Module 3',title:'Build a feasible, safer plan',stepIds:['l2-deep-6','l2-deep-7','l2-deep-8','l2-deep-9'],summary:'Integrate food access, fish guidance, products, medicines and exposures without blanket rules.'},
      {id:'counsel',label:'Module 4',title:'Counsel and coordinate care',stepIds:['l2-deep-10','l2-deep-11','l2-deep-12'],summary:'Use READY, teach-back, scope boundaries and careful test reasoning in realistic decisions.'}
    ],
    recap:['Start early without blame or promises.','Assess adequacy through access, intake, absorption, use, losses and function.','Use the right nutrient number for the right purpose.','Reduce risk with precise guidance rather than blanket prohibitions.','Choose a feasible next action and coordinate care beyond scope.'],
    application:{title:'Four months before pregnancy',scenario:'A vegan client plans pregnancy in four months, often misses lunch at work and reports heavy periods.',stages:[{title:'1 · Ask',prompt:'What information would make the next step safer and more realistic?',points:['Meal access and whether enough food is available across the day.','Reliable vitamin B12 sources and the actual supplement label, including folic acid.','Bleeding history, existing care and what support the client wants.']},{title:'2 · Support',prompt:'What can a nutrition counsellor support within scope?',points:['Reliable B12 and iron food sources without diagnosing a deficiency.','Routine folic-acid guidance and a portable lunch that fits the work setting.','One achievable action chosen with the client.']},{title:'3 · Coordinate',prompt:'What needs appropriately qualified clinical review?',points:['Heavy bleeding and possible iron-status assessment.','Medication, diagnosed conditions or treatment-dose supplement questions.','Any concern beyond the counsellor’s training, competence or legal role.']}]}
  },
  'lesson-3':{
    duration:'80–100 minutes · saves as you go',level:'Nutrition counsellor in training',
    why:'Pregnancy nutrition requires you to connect timing, physiology, nutrient numbers, food safety, symptoms and urgent referral—without turning population guidance into an individual prescription.',
    outcomes:['Distinguish pregnancy clocks, outcomes and placental transfer mechanisms.','Explain maternal adaptations without confusing concentration with total amount.','Use energy, macronutrient and prenatal micronutrient numbers with their correct labels.','Apply food-safety, symptom and weight-gain guidance without stereotypes or rigid rules.','Recognize hypertension, diabetes and multifetal-pregnancy concerns that change the priority.'],
    integratedSteps:[
      {id:'l3-deep-1',title:'Name the clock before using the number',sectionIds:['l3-2'],activityId:'l3-interactive-1',keyIdea:'Gestational age, post-conception age and developmental timing answer different questions.'},
      {id:'l3-deep-2',title:'Treat the placenta as a selective interface',sectionIds:['l3-3'],activityId:'l3-interactive-2',keyIdea:'The placenta exchanges, modifies and produces substances while maternal and fetal circulation remain separate.'},
      {id:'l3-deep-3',title:'Interpret maternal adaptation correctly',sectionIds:['l3-4'],activityId:'l3-interactive-3',keyIdea:'A lower concentration can result from plasma expansion; it neither proves nor rules out deficiency.'},
      {id:'l3-deep-4',title:'Add nourishment without prescribing a menu',sectionIds:['l3-5'],activityId:'l3-interactive-4',keyIdea:'Pregnancy increases needs, but nutrient density and sufficient total energy are separate questions.'},
      {id:'l3-deep-5',title:'Keep folate form, figure and timing together',sectionIds:['l3-6'],prompt:'How can 400 mcg folic acid and 600 mcg DFE both be relevant without being the same instruction?',keyIdea:'One number describes prevention guidance for a specific form; the other describes a total-intake reference adjusted for source.'},
      {id:'l3-deep-6',title:'Read the full micronutrient picture',sectionIds:['l3-7'],activityId:'l3-interactive-5',keyIdea:'Iron, calcium, vitamin D, B12, iodine and choline each require the correct life-stage number, source and limitation.'},
      {id:'l3-deep-7',title:'Use precise fish, caffeine and alcohol guidance',sectionIds:['l3-8'],prompt:'Why must a fish limit keep both its category and time period?',keyIdea:'Different fish categories use different amounts and time windows; caffeine totals all sources, and no known safe alcohol amount is established in pregnancy.'},
      {id:'l3-deep-8',title:'Discuss food safety and pica without stereotypes',sectionIds:['l3-9'],prompt:'What should replace judgment when someone discloses a pica behaviour?',keyIdea:'Normalize disclosure, identify the substance and frequency, assess risk and coordinate appropriate care without treating a bounded study as an ethnic rule.'},
      {id:'l3-deep-9',title:'Calculate BMI, then interpret cautiously',sectionIds:['l3-10'],activityId:'l3-interactive-7',keyIdea:'Units, pre-pregnancy BMI category and pregnancy type determine the reference range; BMI is not a complete assessment.'},
      {id:'l3-deep-10',title:'Adapt for nausea, reflux and constipation',sectionIds:['l3-11'],activityId:'l3-interactive-6',keyIdea:'Start with tolerated, feasible strategies and escalate persistent vomiting, dehydration or other red flags.'},
      {id:'l3-deep-11',title:'Recognize hypertension and preeclampsia',sectionIds:['l3-12'],activityId:'l3-interactive-8',keyIdea:'Preeclampsia is a multisystem clinical condition; urgent symptoms change the priority from meal planning to medical assessment.'},
      {id:'l3-deep-12',title:'Follow maternal glucose to fetal insulin',sectionIds:['l3-13'],prompt:'Whose insulin drives fetal growth when maternal glucose is elevated?',keyIdea:'Maternal glucose crosses the placenta; the fetus responds with its own insulin, which can increase growth and energy storage.'},
      {id:'l3-deep-13',title:'Adjust reasoning for twins and multifetal pregnancy',sectionIds:['l3-14'],prompt:'Why is “double everything” unsafe advice for a twin pregnancy?',keyIdea:'Risk, weight-gain ranges and monitoring change with multifetal pregnancy, but nutrients and supplements do not all double uniformly.'},
      {id:'l3-deep-14',title:'Apply A-C-T to three counselling cases',sectionIds:['l3-15'],prompt:'What is the first step when a case contains a possible urgent symptom?',keyIdea:'Assess urgency first, connect the physiology without overclaiming, then take the appropriate support or referral action.'}
    ],
    modules:[
      {id:'timing',label:'Module 1',title:'Read timing and transfer correctly',stepIds:['l3-deep-1','l3-deep-2'],summary:'Separate pregnancy clocks and understand the placenta as a selective interface rather than a protective wall.'},
      {id:'adaptation',label:'Module 2',title:'Understand adaptation and adequacy',stepIds:['l3-deep-3','l3-deep-4'],summary:'Connect circulation, metabolism, energy and macronutrient needs without oversimplifying.'},
      {id:'numbers',label:'Module 3',title:'Master prenatal numbers and exposures',stepIds:['l3-deep-5','l3-deep-6','l3-deep-7','l3-deep-8'],summary:'Use folate, micronutrient, fish, caffeine, alcohol and food-safety guidance precisely.'},
      {id:'practice',label:'Module 4',title:'Work through weight and symptoms',stepIds:['l3-deep-9','l3-deep-10'],summary:'Calculate the reference correctly, then adapt support to symptoms, barriers and red flags.'},
      {id:'clinical',label:'Module 5',title:'Recognize conditions that change priority',stepIds:['l3-deep-11','l3-deep-12','l3-deep-13','l3-deep-14'],summary:'Connect hypertension, diabetes, multifetal pregnancy and urgent case reasoning to safe next actions.'}
    ],
    recap:['Name the clock and outcome before interpreting a pregnancy number.','Treat placental transfer and maternal adaptation as mechanisms, not slogans.','Keep every nutrient number attached to its form, source and purpose.','Adapt food and symptom guidance to the person while watching for red flags.','When urgency or clinical complexity rises, coordinate care rather than extending meal planning.']
  }
};
